import ReactGA from "react-ga4";

// Replace with your GA4 Measurement ID
const GA_MEASUREMENT_ID = "G-TKBQR7BWCC";  // Replace with your actual GA4 ID

export const initGA = () => {
    ReactGA.initialize(GA_MEASUREMENT_ID);
};

export const setUserId = (userId) => {
    console.log(`Setting User ID: ${userId}`);  // Debugging
    ReactGA.set({ user_id: userId });
};

export const logEvent = (eventName, params = {}) => {
    console.log(`Logging Event: ${eventName}`, params);  // Debugging
    ReactGA.event(eventName, params);
};

export const logLogin = (userId) => {
    setUserId(userId);  // Set user in GA
    logEvent("user_login", { user_id: userId, timestamp: new Date().toISOString() });
};

export const logLogout = (userId, sessionDuration) => {
    logEvent("user_logout", { user_id: userId, session_duration: sessionDuration });
};

export const logPageView = () => {
    console.log("Logging Page View");  // Debugging
    ReactGA.send("pageview");
};
